package com.nigson.acceptance.pricing;
import com.nigson.commerce.affiliate.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import static org.assertj.core.api.Assertions.*;

@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class AffiliateCommissionsTest {
 private PricingFixture f;private AffiliateCommissions commissions;private TransactionTemplate tx;private com.nigson.commerce.reward.RewardOperations operations;
 private final Instant now=Instant.parse("2026-11-20T00:00:00Z");
 @BeforeAll void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null);var jdbc=new JdbcTemplate(new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime"));var manager=new DataSourceTransactionManager(jdbc.getDataSource());f=new PricingFixture(jdbc,manager);var clock=Clock.fixed(now,ZoneOffset.UTC);commissions=new AffiliateCommissions(jdbc,new AuditWriter(jdbc,clock,f.metrics),clock,3,manager);operations=new com.nigson.commerce.reward.RewardConfiguration().rewardOperations(jdbc,new AuditWriter(jdbc,clock,f.metrics),commissions);tx=new TransactionTemplate(manager);}
 @AfterAll void cleanup(){if(f!=null)f.close();}
 private void rollback(Runnable test){tx.executeWithoutResult(s->{s.setRollbackOnly();test.run();});}
 private record Order(UUID id,UUID line,UUID attempt){}
 private Order order(boolean verified,UUID affiliate,boolean policy){UUID order=UUID.randomUUID(),line=UUID.randomUUID(),attempt=UUID.randomUUID();var attribution=new HashMap<String,Object>();attribution.put("affiliatePartyId",affiliate);if(policy){attribution.put("commissionRate","0.05");attribution.put("holdDays",7);}String snapshot=EventCodec.JSON.writeValueAsString(Map.of("affiliateAttribution",attribution));
  f.jdbc.update("INSERT INTO commerce.sales_order(id,created_by,updated_by,order_number,party_id,market_id,status,payment_status,fulfillment_status,currency_code,subtotal,discount_total,tax_total,delivery_total,grand_total,address_snapshot,commercial_snapshot,carrier_quote_id,carrier_snapshot) VALUES (?,'test','test',?, ?,?,'PAID','PAID','UNFULFILLED','NGN',1000,100,90,50,1040,'{}',?::jsonb,?,'{}')",order,"SYN_"+order.toString().replace("-",""),f.customer.party(),f.market,snapshot,f.carrier);
  f.jdbc.update("INSERT INTO commerce.order_line(id,created_by,order_id,sku_id,sku_code,product_name,unit,quantity,unit_amount,discount_amount,tax_amount,line_total,price_book_revision) VALUES (?,'test',?,?,'SYNTHETIC','Synthetic commission','EA',1,1000,100,90,990,0)",line,order,f.sku);
  f.jdbc.update("INSERT INTO commerce.payment_attempt(id,created_by,updated_by,order_id,provider,reference,merchant_account,expected_amount,currency_code,state,verified_at) VALUES (?,'test','test',?,'PAYSTACK',?,'synthetic',1040,'NGN',?,?)",attempt,order,"synthetic-"+attempt,verified?"SUCCEEDED":"UNKNOWN",verified?java.sql.Timestamp.from(now.minusSeconds(86400)):null);
  if(verified)f.jdbc.update("INSERT INTO commerce.payment_transaction(id,created_by,attempt_id,provider_transaction_id,settled_amount,currency_code,provider_status,settled_at,verification_hash) VALUES (?,'test',?,?,1040,'NGN','success',?,?)",UUID.randomUUID(),attempt,"synthetic-"+attempt,java.sql.Timestamp.from(now.minusSeconds(86400)),"1".repeat(64));return new Order(order,line,attempt);
 }
 private UUID refund(Order order,String amount,String state){UUID id=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.refund(id,created_by,updated_by,order_id,attempt_id,request_key,amount,currency_code,state,reason,requested_by,provider_reference) VALUES (?,'test','test',?,?,?,?::numeric,'NGN',?,'Synthetic refund',?,?)",id,order.id(),order.attempt(),id.toString(),amount,state,f.finance.party(),"synthetic-"+id);f.jdbc.update("INSERT INTO commerce.refund_line(id,created_by,updated_by,refund_id,order_line_id,quantity,amount) VALUES (?,'test','test',?,?,0.5,?::numeric)",UUID.randomUUID(),id,order.line(),amount);return id;}
 private UUID delivered(Order order,Instant when){UUID id=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.shipment(id,created_by,updated_by,order_id,status,delivered_at) VALUES (?,'test','test',?,'DELIVERED',?)",id,order.id(),java.sql.Timestamp.from(when));f.jdbc.update("UPDATE commerce.sales_order SET status='DELIVERED',fulfillment_status='DELIVERED' WHERE id=?",order.id());return id;}
 @Test void verifiedNetMerchandiseEarnsOnceAndDoesNotExposeAnotherAffiliatesOrders(){rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());operations.orderSettled(order.id(),UUID.randomUUID());var result=commissions.earnings(f.finance.party(),0);assertThat(result.pending()).isEqualTo("45.00");assertThat(result.totalElements()).isEqualTo(1);assertThat(result.items().getFirst().earned()).isEqualTo("45.00");assertThat(commissions.earnings(f.customer.party(),0).items()).isEmpty();});}
 @Test void unverifiedSelfAndPrePolicyOrdersDoNotEarn(){rollback(()->{for(var order:List.of(order(false,f.finance.party(),true),order(true,f.customer.party(),true),order(true,f.finance.party(),false)))operations.orderSettled(order.id(),UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).totalElements()).isZero();assertThat(commissions.earnings(f.customer.party(),0).totalElements()).isZero();});}
 @Test void onlyCompleteDeliveryAndFullSevenDaysQualify(){rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());UUID shipment=delivered(order,now.minus(Duration.ofDays(7)).plusSeconds(1));assertThat(commissions.earnings(f.finance.party(),0).pending()).isEqualTo("45.00");f.jdbc.update("UPDATE commerce.shipment SET delivered_at=? WHERE id=?",java.sql.Timestamp.from(now.minus(Duration.ofDays(7))),shipment);assertThat(commissions.earnings(f.finance.party(),0).available()).isEqualTo("45.00");f.jdbc.update("INSERT INTO commerce.shipment(id,created_by,updated_by,order_id,status) VALUES (?,'test','test',?,'SHIPPED')",UUID.randomUUID(),order.id());assertThat(commissions.earnings(f.finance.party(),0).available()).isEqualTo("0.00");});}
 @Test void unresolvedRefundHoldsAndSuccessReversesProportionallyWithoutDuplicates(){rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());delivered(order,now.minus(Duration.ofDays(8)));UUID refund=refund(order,"495.00","UNKNOWN");operations.refundSettled(refund,UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).held()).isEqualTo("45.00");f.jdbc.update("UPDATE commerce.refund SET state='SUCCEEDED' WHERE id=?",refund);f.jdbc.update("UPDATE commerce.sales_order SET payment_status='PARTIALLY_REFUNDED' WHERE id=?",order.id());operations.refundSettled(refund,UUID.randomUUID());operations.refundSettled(refund,UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).available()).isEqualTo("22.50");assertThat(commissions.earnings(f.finance.party(),0).reversed()).isEqualTo("22.50");UUID second=refund(order,"495.00","SUCCEEDED");operations.refundSettled(second,UUID.randomUUID());operations.refundSettled(refund,UUID.randomUUID());var result=commissions.earnings(f.finance.party(),0);assertThat(result.reversed()).isEqualTo("45.00");assertThat(result.available()).isEqualTo("0.00");assertThat(result.items().getFirst().state()).isEqualTo("REVERSED");});}
 @Test void runtimeCannotRewriteFinancialEntries(){rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());assertThatThrownBy(()->f.jdbc.update("UPDATE commerce.affiliate_commission_entry SET amount=999 WHERE order_id=?",order.id())).isInstanceOf(org.springframework.dao.DataAccessException.class);});}
 @Test void populatedLedgerRefusesRollback()throws Exception {String sql;try(var stream=getClass().getResourceAsStream("/db/changelog/051-bp3-affiliate-commission-rollback.sql")){sql=new String(stream.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());var nested=new TransactionTemplate(f.manager);nested.setPropagationBehavior(org.springframework.transaction.TransactionDefinition.PROPAGATION_NESTED);assertThatThrownBy(()->nested.executeWithoutResult(s->f.jdbc.execute(sql))).isInstanceOfSatisfying(org.springframework.dao.DataAccessException.class,failure->assertThat(failure.getMostSpecificCause().getMessage()).startsWith("ERROR: Populated table commerce.affiliate_commission_entry: use expand/contract migration"));assertThat(commissions.earnings(f.finance.party(),0).pending()).isEqualTo("45.00");});}
 @Test void refundRoundingUsesCumulativeMerchandiseAndNeverExceedsEarning(){rollback(()->{var order=order(true,f.finance.party(),true);operations.orderSettled(order.id(),UUID.randomUUID());UUID first=refund(order,"0.10","SUCCEEDED");operations.refundSettled(first,UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).reversed()).isEqualTo("0.00");UUID second=refund(order,"0.10","SUCCEEDED");operations.refundSettled(second,UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).reversed()).isEqualTo("0.01");UUID last=refund(order,"989.80","SUCCEEDED");operations.refundSettled(last,UUID.randomUUID());operations.refundSettled(second,UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).reversed()).isEqualTo("45.00");});}
 @Test void businessPurchasesAndForeignAccountParametersAreRejected(){rollback(()->{var order=order(true,f.finance.party(),true);UUID organization=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.organization(id,created_by,updated_by,name,country_code,status) VALUES (?,'test','test','Synthetic business','NG','ACTIVE')",organization);f.jdbc.update("UPDATE commerce.sales_order SET organization_id=? WHERE id=?",organization,order.id());operations.orderSettled(order.id(),UUID.randomUUID());assertThat(commissions.earnings(f.finance.party(),0).totalElements()).isZero();});
  var links=org.mockito.Mockito.mock(AffiliateLinks.class);org.mockito.Mockito.when(links.status(f.customer)).thenReturn(new AffiliateLinks.Status("ACTIVE"));var controller=new AffiliateEarningsController(links,commissions);var request=new org.springframework.mock.web.MockHttpServletRequest();request.addParameter("partyId",f.finance.party().toString());try{org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(f.customer,null,List.of()));assertThatThrownBy(()->controller.earnings(request)).hasMessage("VALIDATION_ERROR");request.removeParameter("partyId");assertThat(controller.earnings(request).getBody().items()).isEmpty();org.mockito.Mockito.when(links.status(f.customer)).thenReturn(new AffiliateLinks.Status("NONE"));assertThatThrownBy(()->controller.earnings(request)).hasMessage("ACCESS_DENIED");}catch(java.io.IOException failure){throw new RuntimeException(failure);}finally{org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 }
}
